// Prototype only: synthetic data, in-memory changes, no account/payment/sync services.
const initial=[{id:1,title:'整理下周的课程安排',list:'学习',time:'',note:'核对课程时间，留出复习时间。',done:false},{id:2,title:'和小组讨论展示提纲',list:'学习',time:'10:00',note:'带上目前的提纲，确认每个人负责的部分。',done:false},{id:3,title:'完成产品调研笔记',list:'个人项目',time:'14:30',note:'整理今天的观察，把需要补证的地方单独列出。',done:false},{id:4,title:'买水果和早餐',list:'生活',time:'',note:'苹果、牛奶、全麦面包。',done:false},{id:5,title:'散步二十分钟',list:'生活',time:'18:00',note:'',done:false},{id:6,title:'给绿植浇水',list:'生活',time:'',note:'',done:true}];
const articles=[{category:'开始使用',title:'如何添加任务？',body:'打开应用的「今天」，输入任务名称并选择「添加」。点击任务可以查看备注；完成后，点击任务前的圆圈。你仍可以在「已完成」中找到这件事，并重新打开。'}, {category:'任务与清单',title:'任务和笔记有什么区别？',body:'任务是需要完成的事情，具有完成状态；笔记用于保存信息，没有完成状态。示例中的「整理下周的课程安排」是一项任务，任务详情中的备注保存与它有关的信息。'}, {category:'任务与清单',title:'日期和具体时间有什么区别？',body:'只安排日期的任务没有具体时刻，不应被理解为当天零点。设定具体时刻的任务还需记录所属时区。本原型用同一天的示例数据展示两种任务。'}, {category:'离线与同步',title:'离线时，我还能做什么？',body:'纸序的既定产品目标是支持普通任务离线查看、创建和编辑，恢复联网后再同步。本页为交互演示，顶部可以模拟离线和恢复联网；所有数据仅保存在当前页面，刷新后重置。真实离线存储与同步尚未实现。'}, {category:'离线与同步',title:'本地模式和离线编辑一样吗？',body:'不一样。本地模式无需注册账号，不提供跨设备同步；离线编辑指已登录用户在断网时继续处理普通任务。当前示例不建立真实账号，也不验证这两种存储模式。'}, {category:'会员与订阅',title:'现在可以购买高级会员吗？',body:'暂时不可以。此处只审阅会员页面和入口，具体功能权益、价格、周期、容量与购买渠道尚待决策。目前没有真实订单或付款服务。'}];
let tasks=structuredClone(initial),selected=1,filter='今天',state='normal',pending=0,counter=10,query='',topic='全部',timer;
let scene=new URLSearchParams(location.search).get('scene')||'home';if(!['home','app','help','membership'].includes(scene))scene='home';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(s,text,cls='')=>`<a href="?scene=${s}" data-scene="${s}" class="${cls}" ${scene===s?'aria-current="page"':''}>${text}</a>`;
const brand=()=>'<div class="brand"><span class="brand-icon" aria-hidden="true"></span><div><strong>纸序</strong><small>Paperdo</small></div></div>';
const header=()=>`<header class="site-header">${link('home',brand(),'brand-link')}<nav class="site-nav" aria-label="网站导航">${link('home','产品')}${link('help','帮助')}${link('membership','会员')}${link('app','打开纸序','primary')}</nav></header>`;
const footer=()=>`<footer class="site-footer"><span>纸序 Paperdo · 在一页一页里，把生活轻轻安顿。</span><nav aria-label="页脚导航">${link('help','使用帮助')}${link('membership','会员说明')}</nav></footer>`;
function homepage(){return `${header()}<main id="main" class="site-main" tabindex="-1"><section class="product-hero"><p class="eyebrow">纸序 PAPERDO</p><h1>把每一天，<br>安排得更清晰。</h1><p>记录待办，整理计划，专注眼前的事。<br>让工作和生活，都有自己的节奏。</p><div class="actions">${link('app','打开纸序','cta primary')}${link('help','使用指南','cta outline')}</div><span class="hero-caption">交互原型 · 无需注册</span></section><section class="product-window" aria-label="纸序任务工作区预览"><div class="product-window-bar"><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>纸序 · 今天</span><a href="?scene=app" data-scene="app">完整体验 ↗</a></div><iframe title="纸序任务工作区交互预览" src="?scene=app" loading="lazy"></iframe></section><section class="feature-row" aria-label="日常任务体验"><article class="feature"><span>快速记录</span><h2>想到，就记下来。</h2><p>输入任务后按回车，继续记录下一件事。没有日期的想法先放进收集箱。</p></article><article class="feature"><span>清晰安排</span><h2>计划和细节，一眼看清。</h2><p>用清单整理不同的事，在任务旁查看日期、备注和检查项。</p></article><article class="feature"><span>轻松推进</span><h2>完成一件，再向前一步。</h2><p>勾选已完成的任务；误操作时可以撤销，记录仍然清晰可回看。</p></article></section></main>${footer()}`}
function status(){return state==='offline'?`<span class="status offline"><span class="dot"></span>离线 · ${pending?pending+' 项变更待同步':'可继续编辑'}</span>`:`<span class="status"><span class="dot"></span>${state==='loading'?'正在读取':state==='error'?'读取失败':'已同步'}</span>`}
const visible=()=>tasks.filter(t=>filter==='已完成'?t.done:filter==='全部'?true:filter==='今天'?!t.done:t.list===filter&&!t.done);
const row=t=>`<div class="task ${t.done?'done':''} ${selected===t.id?'selected':''}"><button class="check" data-done="${t.id}" aria-label="${t.done?'重新打开':'完成'}：${esc(t.title)}" aria-pressed="${t.done}"><span class="circle">${t.done?'✓':''}</span></button><button class="task-open" data-select="${t.id}" aria-label="查看详情：${esc(t.title)}"><span class="task-title">${esc(t.title)}</span><span class="task-meta">${esc(t.list)} · 今天</span></button><span class="time">${esc(t.time)}</span></div>`;
function detail(){const t=tasks.find(t=>t.id===selected);if(!t||state==='loading'||state==='error')return '<aside class="detail"><p class="eyebrow">任务详情</p><p class="muted">选择一件事，展开它的详情。</p></aside>';return `<aside class="detail" aria-label="任务详情"><button class="close-detail outline" id="close-detail">收起详情</button><p class="eyebrow">任务详情</p><h2>${esc(t.title)}</h2><dl><dt>清单</dt><dd>${esc(t.list)}</dd><dt>日期</dt><dd>10 月 18 日${t.time?' · '+t.time:' · 仅日期'}</dd><dt>状态</dt><dd>${t.done?'已完成':'未完成'}</dd></dl><form id="note-form"><label for="task-note">备注</label><textarea id="task-note" maxlength="2000">${esc(t.note)}</textarea><button class="outline save" type="submit">保存备注</button></form><p class="hint">${state==='offline'?'修改会计入待同步；本原型仅在当前页面保存。':'每一步，都可以慢慢来。'}</p></aside>`}
function app(){const arr=visible();let content='';if(state==='loading')content='<section class="state-box" aria-label="加载中"><h2>正在读取你的清单…</h2><p>稍等一下，事情正在回到这一页。</p><div class="skeleton"></div><div class="skeleton short"></div><button class="outline" data-state="normal">结束加载演示</button></section>';else if(state==='error')content='<section class="state-box"><div class="state-symbol">!</div><h2>暂时没有读到清单</h2><p>请稍后重试。这里还没有显示任务，不代表清单已经变空。</p><button class="primary retry" data-state="normal">重新加载</button><button data-scene="help">查看帮助</button></section>';else content=`${state==='offline'?`<div class="offline-help"><span>可以继续处理普通任务。当前同步为模拟演示。</span><button class="outline" data-state="normal">模拟恢复联网</button></div>`:''}<form class="entry" id="add-form"><label for="new-task">添加今天的任务</label><input id="new-task" maxlength="160" placeholder="添加一件今天要做的事…" autocomplete="off" required><button class="primary" type="submit">＋ 添加</button></form><div class="list-heading"><span>${esc(filter)}</span><span>${arr.length} 件事</span></div>${arr.length?arr.map(row).join(''):`<section class="state-box"><div class="state-symbol">○</div><h2>${filter==='已完成'?'还没有已完成的任务':'这一页，留给新的开始。'}</h2><p>${filter==='已完成'?'完成的事情会出现在这里。':'想到要做的事时，把它写下来。先写一件就好。'}</p><button class="outline" id="focus-add">写下第一件事</button></section>`}`;
return `<div class="app-top"><span>纸序 · 应用体验</span><nav aria-label="配套入口">${link('home','返回官网')}${link('help','帮助')}${link('membership','会员')}</nav></div><div class="app A"><aside class="sidebar">${brand()}<nav aria-label="任务视图">${['今天','全部','已完成'].map(n=>`<button class="nav-button ${filter===n?'active':''}" data-filter="${n}" aria-pressed="${filter===n}">${n}<span class="count">${n==='已完成'?tasks.filter(t=>t.done).length:n==='全部'?tasks.length:tasks.filter(t=>!t.done).length}</span></button>`).join('')}</nav><p class="group">我的清单</p><div class="lists">${['学习','个人项目','生活'].map(n=>`<button class="nav-button ${filter===n?'active':''}" data-filter="${n}" aria-pressed="${filter===n}">${n}</button>`).join('')}</div><div class="sidebar-links"><button data-scene="help">使用帮助 ↗</button><button data-scene="membership">了解高级会员 ↗</button></div><p class="foot">一页一页，<br>把生活轻轻安顿。</p></aside><main id="main" class="workspace" tabindex="-1"><div class="heading"><div><p class="date">2026 年 10 月 18 日 · 星期日</p><h1>${esc(filter)}</h1><span class="muted">${filter==='今天'?'把今天，轻轻安顿。':'每件事，都有位置。'}</span></div>${status()}</div>${content}</main>${detail()}</div>`}
function help(){const matched=articles.filter(a=>(topic==='全部'||a.category===topic)&&(!query||(a.title+a.body).includes(query)));return `${header()}<main id="main" class="site-main" tabindex="-1"><section class="section-intro"><p class="eyebrow">PAPERDO GUIDE</p><h1>需要什么帮助？</h1><p>从第一件任务开始，找到需要的答案。</p></section><form class="help-search" id="search-form"><label for="help-query">搜索使用帮助</label><div class="search-row"><input id="help-query" type="search" value="${esc(query)}" placeholder="试试「添加任务」或「离线」"><button class="primary" type="submit">搜索</button></div></form><div class="help-layout"><nav class="help-topics" aria-label="帮助分类">${['全部','开始使用','任务与清单','离线与同步','会员与订阅'].map(n=>`<button data-topic="${n}" class="${topic===n?'active':''}" aria-pressed="${topic===n}">${n}</button>`).join('')}</nav><section class="help-results"><h2>${query?'搜索结果':topic==='全部'?'从这里开始':esc(topic)} <span class="help-count">· ${matched.length} 篇</span></h2>${matched.length?matched.map(a=>`<details><summary>${esc(a.title)}</summary><p>${esc(a.body)}</p></details>`).join(''):'<div class="state-box"><h3>还没找到相关说明</h3><p>换一个关键词试试，或回到全部分类。</p><button class="outline" id="clear-search">查看全部帮助</button></div>'}<div class="help-tail"><h3>回到事情本身。</h3><p>打开纸序，试着写下今天要做的一件小事。</p>${link('app','返回应用 →','cta outline')}</div></section></div></main>${footer()}`}
function membership(){return `${header()}<main id="main" class="site-main" tabindex="-1"><section class="membership-intro"><p class="eyebrow">PAPERDO MEMBERSHIP</p><h1>让适合自己的工具，<br>陪伴每天的安排。</h1><p>免费用户与高级会员，共用同一份清晰、平静的体验。</p></section><section class="plans" aria-label="会员方案展示"><article class="plan"><p class="eyebrow">日常，从这里开始</p><h2>免费用户</h2><p class="plan-line">使用纸序的免费功能与相应额度。</p><div class="price-placeholder">免费功能范围待确认</div><dl><dt>包含功能</dt><dd>以最终权益方案为准</dd><dt>使用额度</dt><dd>待确定</dd></dl>${link('app','先体验今天的清单','cta outline')}</article><article class="plan premium"><p class="eyebrow">给日常更多支持</p><h2>高级会员</h2><p class="plan-line">在权益有效期内，使用高级功能与相应额度。</p><div class="price-placeholder">价格与订阅周期待确认</div><dl><dt>高级权益</dt><dd>待确定</dd><dt>容量与额度</dt><dd>待确定</dd></dl><button disabled title="价格、权益与购买渠道未确定">暂未开放购买</button></article></section><div class="billing-note">当前为会员页面的结构与视觉预览。价格、功能归属、容量、订阅周期、续费与退款条款另行审定；此处不生成订单、不收款。</div><section class="help-results member-help"><h2>会员相关说明</h2><details><summary>在哪里查看最终权益与价格？</summary><p>方案确定后，会在这里展示清晰的功能对比、额度、价格与适用周期。当前预览不代表任何功能已经划归收费或免费。</p></details><details><summary>购买遇到问题，在哪里寻求帮助？</summary><p>会员说明与帮助中心将保持互通。当前先验证这个入口是否容易找到；正式客服与购买渠道仍待确定。</p></details><p style="margin-top:24px">${link('help','前往帮助中心 →')}</p></section></main>${footer()}`}
function notify(text){clearTimeout(timer);document.getElementById('notice').textContent=text;timer=setTimeout(()=>document.getElementById('notice').textContent='',5000)}
function navigate(next,push=true){scene=next;const url=new URL(location.href);url.searchParams.set('scene',next);if(push)history.pushState(null,'',url);render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true})}
function applyState(next){const wasOffline=state==='offline';state=next;if(next==='empty'){tasks=[];selected=null;pending=0;filter='今天'}if(wasOffline&&next==='normal'){notify('已模拟恢复联网，'+pending+' 项变更已模拟同步。');pending=0}if(scene!=='app')navigate('app');else render()}
function render(){document.getElementById('root').innerHTML=scene==='home'?homepage():scene==='help'?help():scene==='membership'?membership():app();document.getElementById('state-demo').value=state;document.title='纸序 · '+({home:'官网',app:'今天',help:'帮助',membership:'会员'}[scene])+' · 体验原型';bind()}
function bind(){document.querySelectorAll('[data-scene]').forEach(el=>el.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey)return;e.preventDefault();navigate(el.dataset.scene)});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render()});document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>{topic=el.dataset.topic;render()});document.querySelectorAll('[data-state]').forEach(el=>el.onclick=()=>applyState(el.dataset.state));document.querySelectorAll('[data-done]').forEach(el=>el.onclick=()=>{const t=tasks.find(t=>t.id===Number(el.dataset.done));t.done=!t.done;if(state==='offline')pending++;render();notify((t.done?'已完成：':'已重新打开：')+t.title+(state==='offline'?' · 待同步':''))});document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>{selected=Number(el.dataset.select);render();if(innerWidth<1100)document.querySelector('.detail').scrollIntoView({block:'nearest'})});document.getElementById('add-form')?.addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('new-task'),title=input.value.trim();if(!title){input.setCustomValidity('请输入任务名称');input.reportValidity();input.oninput=()=>input.setCustomValidity('');return}tasks.unshift({id:counter++,title,list:['学习','个人项目','生活'].includes(filter)?filter:'生活',time:'',note:'',done:false});if(state==='offline')pending++;if(state==='empty')state='normal';filter='今天';render();document.getElementById('new-task').focus();notify('已添加到今天'+(state==='offline'?' · 待同步':''))});document.getElementById('note-form')?.addEventListener('submit',e=>{e.preventDefault();tasks.find(t=>t.id===selected).note=document.getElementById('task-note').value;if(state==='offline')pending++;render();notify('备注已保存到本次演示'+(state==='offline'?' · 待同步':''))});document.getElementById('search-form')?.addEventListener('submit',e=>{e.preventDefault();query=document.getElementById('help-query').value.trim();render()});document.getElementById('clear-search')?.addEventListener('click',()=>{topic='全部';query='';render()});document.getElementById('close-detail')?.addEventListener('click',()=>{selected=null;render()});document.getElementById('focus-add')?.addEventListener('click',()=>{filter='今天';render();document.getElementById('new-task').focus()})}
document.getElementById('state-demo').onchange=e=>applyState(e.target.value);document.getElementById('reset').onclick=()=>{tasks=structuredClone(initial);selected=1;filter='今天';state='normal';pending=0;query='';topic='全部';render();notify('示例已重置')};window.onpopstate=()=>{const next=new URLSearchParams(location.search).get('scene');scene=['home','app','help','membership'].includes(next)?next:'home';render()};render();


